sys_script.script:
(function() {
    var newStatus = current.getValue('status');
    var oldStatus = previous ? previous.getValue('status') : '';

    // Only check when status changes to verified or closed
    if (newStatus !== 'verified' && newStatus !== 'closed') {
        return;
    }

    // Don't re-validate if already in verified/closed
    if (oldStatus === 'verified' || oldStatus === 'closed') {
        return;
    }

    // Check for outstanding returnable items
    var mi = new GlideRecord('x_2056099_indust_0_maint_mi');
    mi.addQuery('maintenance', current.getUniqueValue());
    mi.addQuery('return_required', true);
    mi.addQuery('status', '!=', 'returned');
    mi.addQuery('status', '!=', 'closed');
    mi.addQuery('status', '!=', 'cancelled');
    mi.query();

    if (mi.hasNext()) {
        var count = mi.getRowCount();
        gs.addErrorMessage('Cannot close maintenance: ' + count + ' returnable item(s) are still outstanding. All returnable tools must be returned before maintenance can be verified or closed.');
        current.setValue('status', 'awaiting_return');
        current.setAbortAction(true);
    }
})();
